Body:
@lithvik-x my custom provider in the opencode.jsonc:
```json
    "minimax": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "MiniMax",
      "options": {
        "baseURL": "https://api.minimax.io/v1",
        "apiKey": "<MY_KEY>"
      },
      "models": {
        "MiniMax-M3": {
          "name": "MiniMax M3",
          "limit": {
            "context": 512000,
            "output": 64000
          },
          "reasoning": true,
          "tool_call": true,
          "options": {
            "reasoning_split": true
          },
          "modalities": {
            "input": ["text", "image"],
            "output": ["text"]
          }
        }
      }
    },
```
i hope it helps!
